import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"CLI & Artisan Commands","description":"Every artisan command Pterodactyl Revamp ships — metric sampling, rollups, health scoring, and rule evaluation — plus the queue worker, cron, cache, and Blueprint commands used to operate the addon.","frontmatter":{"title":"CLI & Artisan Commands","description":"Every artisan command Pterodactyl Revamp ships — metric sampling, rollups, health scoring, and rule evaluation — plus the queue worker, cron, cache, and Blueprint commands used to operate the addon."},"headers":[],"relativePath":"pterodactyl-revamp/user-guide/cli.md","filePath":"pterodactyl-revamp/user-guide/cli.md","lastUpdated":1785513726000}'),n={name:"pterodactyl-revamp/user-guide/cli.md"};function r(l,e,o,p,h,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="cli-artisan-commands" tabindex="-1">CLI &amp; Artisan Commands <a class="header-anchor" href="#cli-artisan-commands" aria-label="Permalink to &quot;CLI &amp; Artisan Commands&quot;">​</a></h1><p>Pterodactyl Revamp ships <strong>four artisan commands</strong>. None of them do heavy work in-process — each one is a thin entrypoint that dispatches a job onto the dedicated <code>revamp</code> queue, so the real work always runs through your queue worker.</p><p>All commands below are run from the panel root (usually <code>/var/www/pterodactyl</code>).</p><hr><h2 id="addon-commands" tabindex="-1">Addon Commands <a class="header-anchor" href="#addon-commands" aria-label="Permalink to &quot;Addon Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Schedule</th><th>What it dispatches</th></tr></thead><tbody><tr><td><code>revamp:sample-metrics</code></td><td>Every 5 minutes</td><td><code>SampleServerMetricsJob</code> (chunked)</td></tr><tr><td><code>revamp:rollup-metrics</code></td><td>Hourly</td><td><code>RollupHourlyMetricsJob</code></td></tr><tr><td><code>revamp:compute-health</code></td><td>Every 10 minutes</td><td><code>ComputeHealthJob</code></td></tr><tr><td><code>revamp:evaluate-rules</code></td><td>Daily at 03:00</td><td><code>EvaluateUpgradeRulesJob</code></td></tr></tbody></table><p>The schedule is registered in <code>RevampServiceProvider</code> at boot time, so it applies identically whether the framework is serving HTTP or running under the CLI. Every scheduled run uses <code>withoutOverlapping()</code> (10 / 30 / 15 / 60 minutes respectively) to prevent a slow run from stacking on top of the previous one.</p><div class="warning custom-block"><p class="custom-block-title">The scheduler only <em>dispatches</em></p><p>These commands put jobs on the <code>revamp</code> queue and exit immediately with <strong>no console output</strong>. If no queue worker is consuming the <code>revamp</code> queue, the commands appear to succeed but nothing is ever sampled, rolled up, or computed. See <a href="#queue-worker">Queue Worker</a>.</p></div><h3 id="revamp-sample-metrics" tabindex="-1"><code>revamp:sample-metrics</code> <a class="header-anchor" href="#revamp-sample-metrics" aria-label="Permalink to &quot;\`revamp:sample-metrics\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revamp:sample-metrics</span></span></code></pre></div><p>Samples resource utilisation for all active servers. It selects every server with a non-null <code>installed_at</code>, walks them ordered by id, and dispatches one <code>SampleServerMetricsJob</code> per <strong>chunk of 50 servers</strong> onto the <code>revamp</code> queue. Each job persists raw samples to <code>revamp_metric_samples</code> via the <code>MetricSamplingService</code>.</p><p>The chunking exists to keep memory pressure flat on panels with thousands of servers.</p><p><strong>Run manually when:</strong> you just installed the addon and want the first samples in the database before the next 5-minute tick, or the queue was down and you want to catch up.</p><h3 id="revamp-rollup-metrics" tabindex="-1"><code>revamp:rollup-metrics</code> <a class="header-anchor" href="#revamp-rollup-metrics" aria-label="Permalink to &quot;\`revamp:rollup-metrics\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revamp:rollup-metrics</span></span></code></pre></div><p>Aggregates raw metric samples into hourly rollups. The dispatched <code>RollupHourlyMetricsJob</code> rolls up the <strong>last 3 hours</strong> (to catch stragglers from late-running sample jobs) and then purges raw samples older than the <code>metrics_retention_days</code> setting.</p><p><strong>Run manually when:</strong> you changed <code>metrics_retention_days</code> and want the purge to apply now, or analytics charts look empty because the queue was stalled.</p><h3 id="revamp-compute-health" tabindex="-1"><code>revamp:compute-health</code> <a class="header-anchor" href="#revamp-compute-health" aria-label="Permalink to &quot;\`revamp:compute-health\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revamp:compute-health</span></span></code></pre></div><p>Computes node and server health snapshots. The dispatched <code>ComputeHealthJob</code> runs the <code>NodeHealthService</code> and <code>ServerHealthService</code>, writing snapshots used by the Health page, node pressure scores, and crash-loop / OOM detection (governed by the <code>health_crash_threshold</code> and <code>health_window_hours</code> settings).</p><p><strong>Run manually when:</strong> the Health page shows stale &quot;last snapshot&quot; timestamps after a queue outage.</p><h3 id="revamp-evaluate-rules" tabindex="-1"><code>revamp:evaluate-rules</code> <a class="header-anchor" href="#revamp-evaluate-rules" aria-label="Permalink to &quot;\`revamp:evaluate-rules\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revamp:evaluate-rules</span></span></code></pre></div><p>Evaluates upgrade recommendation rules against the rollup data. The dispatched <code>EvaluateUpgradeRulesJob</code> runs the <code>UpgradeRuleEngine</code>, which produces the per-server recommendations shown by the analytics endpoints (thresholds, window, cooldown, and message text come from the <code>upgrade_*</code> settings).</p><p><strong>Run manually when:</strong> you changed <code>upgrade_cpu_threshold</code> / <code>upgrade_ram_threshold</code> / <code>upgrade_disk_threshold</code> and want recommendations regenerated before the next 03:00 run.</p><hr><h2 id="operational-commands" tabindex="-1">Operational Commands <a class="header-anchor" href="#operational-commands" aria-label="Permalink to &quot;Operational Commands&quot;">​</a></h2><p>These are stock Pterodactyl/Laravel commands, but the addon depends on them being wired up correctly.</p><h3 id="queue-worker" tabindex="-1">Queue Worker <a class="header-anchor" href="#queue-worker" aria-label="Permalink to &quot;Queue Worker&quot;">​</a></h3><p>The <code>revamp</code> queue carries all metric, health, bulk-operation, and rule-evaluation jobs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=revamp,default</span></span></code></pre></div><p>For production, run it under systemd (or Supervisor) with explicit retry and timeout limits:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=revamp,default</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tries=3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --timeout=120</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">A stopped worker silently breaks the addon</p><p>Bulk operations, metrics, health scores, and recommendations <strong>all</strong> flow through this queue. If the worker is down, the UI still accepts bulk operations — they just never process. Check the worker first when anything looks stuck.</p></div><h3 id="cron-scheduler" tabindex="-1">Cron (Scheduler) <a class="header-anchor" href="#cron-scheduler" aria-label="Permalink to &quot;Cron (Scheduler)&quot;">​</a></h3><p>The four schedules above only fire if Laravel&#39;s scheduler runs every minute:</p><div class="language-cron vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cron</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>* * * * * php /var/www/pterodactyl/artisan schedule:run &gt;&gt; /dev/null 2&gt;&amp;1</span></span></code></pre></div><p>Verify the addon&#39;s schedules are registered:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule:list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revamp</span></span></code></pre></div><p>Expected: four entries — <code>revamp:sample-metrics</code>, <code>revamp:rollup-metrics</code>, <code>revamp:compute-health</code>, <code>revamp:evaluate-rules</code>.</p><h3 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to &quot;Migrations&quot;">​</a></h3><p>Run after every install or upgrade (creates/updates the <code>revamp_*</code> tables):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><h3 id="cache-clearing" tabindex="-1">Cache Clearing <a class="header-anchor" href="#cache-clearing" aria-label="Permalink to &quot;Cache Clearing&quot;">​</a></h3><p>After reinstalling, merging updated <code>PanelFiles/</code>, or when views look stale:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view:clear</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:clear</span></span></code></pre></div><p><code>view:clear</code> recompiles the addon&#39;s patched admin blades (tag pickers on server forms, the port picker, the naming pattern field); <code>config:clear</code> picks up changes to <code>config/revamp.php</code>. Hard-refresh your browser afterwards — the admin UI is blade-rendered.</p><hr><h2 id="blueprint-commands" tabindex="-1">Blueprint Commands <a class="header-anchor" href="#blueprint-commands" aria-label="Permalink to &quot;Blueprint Commands&quot;">​</a></h2><p>When installed as a Blueprint extension (identifier <code>pterodactylrevamp</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install (runs data/install.sh: merges PanelFiles, registers the</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># provider, patches admin blades, runs migrations)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Remove (runs data/remove.sh: undoes core file edits and blade patches)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Release Blueprint&#39;s lock if an install was interrupted mid-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -unlock</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Never stack installs</p><p>Do not run <code>-install</code> twice or layer patches onto a broken install. Remove first, then install fresh:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view:clear</span></span></code></pre></div></div><div class="tip custom-block"><p class="custom-block-title">Development loop</p><p>While developing on the addon itself, the cycle is always <code>-remove</code> → <code>-install</code> → <code>migrate --force</code> → <code>view:clear</code>, then a hard browser refresh.</p></div><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h2><ul><li><strong><a href="/pingless-studios-docs/pterodactyl-revamp/user-guide/api">API Reference →</a></strong> — every admin, application, and client API endpoint the addon exposes.</li><li><strong><a href="/pingless-studios-docs/pterodactyl-revamp/getting-started/installation">Installation →</a></strong> — full install walkthrough for both Blueprint and standalone paths.</li></ul>`,56)])])}const k=a(n,[["render",r]]);export{u as __pageData,k as default};
